    const dialogVisible = ref(false);
    const form = reactive({
      containerName: '',
      routes: [{
        targetIp: '',
        nextHopIp: ''
      }]
    });

    // ✅ 打开弹窗方法（并初始化表单）
    const openDialog = () => {
      form.containerName = '';
      form.routes = [{
        targetIp: '',
        nextHopIp: ''
      }];
      dialogVisible.value = true;
    };

    // 添加一个路由项
    const addRoute = () => {
      form.routes.push({
        targetIp: '',
        nextHopIp: ''
      });
    };

    // 删除一个路由项
    const removeRoute = index => {
      form.routes.splice(index, 1);
    };

    // 提交路由数据
    const submitRoutes = async () => {
      if (!form.containerName || form.routes.some(r => !r.targetIp || !r.nextHopIp)) {
        ElMessage.warning('请填写完整容器名称和路由信息');
        return;
      }
      try {
        await axios.post(`http://localhost:8081/bird/add?containerName=${encodeURIComponent(form.containerName)}`, form.routes);
        ElMessage.success('静态路由添加成功');
        dialogVisible.value = false;
      } catch (err) {
        console.error(err);
        ElMessage.error('添加失败：' + (err.response?.data || err.message));
      }
    };

    // ✅ 暴露 openDialog 方法供外部调用
    __expose({
      openDialog
    });
    const __returned__ = {
